import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.io.File;import java.sql.*;import java.time.*;import java.util.*;
public class ReportsPanel extends JPanel {
 private final JTabbedPane reports=new JTabbedPane();
 public ReportsPanel(){setLayout(new BorderLayout());reports.addTab("ESIC",new ReportView(0));reports.addTab("EPF",new ReportView(1));reports.addTab("TDS",new ReportView(2));reports.addTab("Bank Payment",new ReportView(3));add(reports,BorderLayout.CENTER);PayrollEvents.onAttendanceSaved(()->{if(isShowing())refresh();});}
 public void refresh(){for(int i=0;i<reports.getTabCount();i++)if(reports.getComponentAt(i) instanceof ReportView view)view.reload();}
 private static final class ReportView extends JPanel {
  private final int type;private final JComboBox<String> year=FinancialYear.selector(FinancialYear.currentStart());private final JTabbedPane months=new JTabbedPane(JTabbedPane.TOP,JTabbedPane.WRAP_TAB_LAYOUT);private final JTextField search=new JTextField(22);private final JButton export=new JButton("Export to Excel");private final JScrollPane scroll=new JScrollPane();private int financialYear=FinancialYear.currentStart();private DefaultTableModel model;private TableRowSorter<DefaultTableModel> sorter;
  ReportView(int type){super(new BorderLayout());this.type=type;JPanel fy=new JPanel(new FlowLayout(FlowLayout.LEFT));fy.add(new JLabel(title()+" - Financial Year:"));fy.add(year);JButton open=new JButton("Open Year");open.addActionListener(e->{financialYear=FinancialYear.parse(String.valueOf(year.getSelectedItem()));buildMonths();});fy.add(open);add(fy,BorderLayout.NORTH);months.addChangeListener(e->reload());add(months,BorderLayout.CENTER);search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){private void apply(){if(sorter!=null)sorter.setRowFilter(search.getText().trim().isEmpty()?null:RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(search.getText().trim()),0,1));}public void insertUpdate(javax.swing.event.DocumentEvent e){apply();}public void removeUpdate(javax.swing.event.DocumentEvent e){apply();}public void changedUpdate(javax.swing.event.DocumentEvent e){apply();}});export.addActionListener(e->export());buildMonths();}
  private String title(){return switch(type){case 0->"ESIC";case 1->"EPF";case 2->"TDS";default->"Bank Payment";};}
  private void buildMonths(){int selected=Math.max(0,months.getSelectedIndex());months.removeAll();for(int i=0;i<12;i++){YearMonth p=FinancialYear.month(financialYear,i);months.addTab(FinancialYear.shortName(p),new JPanel());JLabel l=new JLabel(FinancialYear.shortName(p),SwingConstants.CENTER);l.setPreferredSize(new Dimension(80,30));l.setForeground(Color.WHITE);months.setTabComponentAt(i,l);}months.setSelectedIndex(Math.min(selected,11));reload();}
  private void reload(){int index=months.getSelectedIndex();if(index<0)return;YearMonth p=FinancialYear.month(financialYear,index);model=new DefaultTableModel(columns(),0){public boolean isCellEditable(int r,int c){return false;}};JTable table=new JTable(model);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);UIStyleUtility.applyProfessionalTableStyle(table);for(int i=0;i<table.getColumnCount();i++)table.getColumnModel().getColumn(i).setPreferredWidth(type==0&&i==3?430:(type==1&&i>=3?190:(i<3?180:170)));sorter=new TableRowSorter<>(model);table.setRowSorter(sorter);scroll.setViewportView(table);scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);if(type==0)loadEsic(p);else if(type==1)loadEpf(p);else if(type==2)loadTds(p);else loadBankPayment(p);JPanel actions=new JPanel(new BorderLayout());JPanel left=new JPanel(new FlowLayout(FlowLayout.LEFT));left.add(new JLabel("Search Employee ID/Name:"));left.add(search);actions.add(left,BorderLayout.WEST);JPanel right=new JPanel(new FlowLayout(FlowLayout.RIGHT));right.add(export);actions.add(right,BorderLayout.EAST);JPanel sheet=new JPanel(new BorderLayout());sheet.add(actions,BorderLayout.NORTH);sheet.add(scroll,BorderLayout.CENTER);months.setComponentAt(index,sheet);months.revalidate();months.repaint();}
  private String[] columns(){return switch(type){case 0->new String[]{"Employee ID","IP Number","IP Name","No. of Days for which wages paid/payable during the month","Total Monthly Wages","ESIC"};case 1->new String[]{"Employee ID","UAN","Member Name","Gross Wages","EPF Wages","EPS Wages","EDLI Wages","EPF Contribution Remitted","EPS Contribution Remitted","EPF–EPS Difference Remitted","NCP Days","Refund of Advances"};case 2->new String[]{"Employee ID","Employee Name","Gross Salary","TDS / Income Tax"};default->new String[]{"Employee ID","Employee Name","Bank Name","Account Number","IFSC Code","Net Payable Salary"};};}
  private void loadEsic(YearMonth period){for(Employee employee:new EmployeeDAO().listForMonth("",period))SalaryCalculationEngine.calculate(employee,period);String fy=FinancialYear.text(period.getMonthValue()>=4?period.getYear():period.getYear()-1),expandedFy=period.getMonthValue()>=4?period.getYear()+"-"+(period.getYear()+1):(period.getYear()-1)+"-"+period.getYear(),month=FinancialYear.shortName(period),attendanceMonth=period.toString();String sql="SELECT e.employee_id,e.esic,e.employee_name,COALESCE(a.days_payable,0),COALESCE(s.basic_pay,0),COALESCE(d.esic,0),e.status,e.joining_date,e.leaving_date,(SELECT esic_wage_threshold FROM settings_deduction_rules WHERE is_deleted=0 ORDER BY id LIMIT 1) FROM employee_master_data e LEFT JOIN attendance a ON a.employee_id=e.employee_id AND a.month=? AND a.fy IN (?,?) AND a.is_deleted=0 LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy IN (?,?) AND s.is_deleted=0 LEFT JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy IN (?,?) AND d.is_deleted=0 WHERE e.is_deleted=0 AND e.esic IS NOT NULL AND TRIM(e.esic)<>'' AND UPPER(TRIM(e.esic)) NOT IN ('NA','N/A') ORDER BY e.employee_id";try(Connection c=DBConnection.getConnection();PreparedStatement q=c==null?null:c.prepareStatement(sql)){if(q==null)return;int i=1;q.setString(i++,attendanceMonth);q.setString(i++,fy);q.setString(i++,expandedFy);q.setString(i++,month);q.setString(i++,fy);q.setString(i++,expandedFy);q.setString(i++,month);q.setString(i++,fy);q.setString(i++,expandedFy);ResultSet r=q.executeQuery();while(r.next()){double wages=r.getDouble(5),threshold=r.getDouble(10);boolean hasThreshold=!r.wasNull();if(!activeStatus(r.getString(7))||!eligible(r.getString(8),r.getString(9),period)||(hasThreshold&&wages>threshold))continue;model.addRow(new Object[]{r.getString(1),r.getString(2),r.getString(3),Money.round(r.getDouble(4)),Money.round(wages),Money.round(r.getDouble(6))});}}catch(SQLException ignored){}}
  private void loadEpf(YearMonth period){java.util.Map<String,Employee> employees=new java.util.HashMap<>();for(Employee employee:new EmployeeDAO().listForMonth("",period)){employees.put(employee.getId(),employee);SalaryCalculationEngine.calculate(employee,period);}double epfRate=CompanyPolicyStore.hasDeduction("EPF")?CompanyPolicyStore.deduction("EPF"):12,epsValue=CompanyPolicyStore.hasDeduction("EPS")?CompanyPolicyStore.deduction("EPS"):8.33;boolean epsPercentage=CompanyPolicyStore.deductionPercentage("EPS");String fy=FinancialYear.text(period.getMonthValue()>=4?period.getYear():period.getYear()-1),expandedFy=period.getMonthValue()>=4?period.getYear()+"-"+(period.getYear()+1):(period.getYear()-1)+"-"+period.getYear(),month=FinancialYear.shortName(period);String sql="SELECT e.employee_id,e.uan,e.employee_name,COALESCE(e.epf_ceiling,0),COALESCE(a.total_working_days,0),COALESCE(a.days_payable,0),COALESCE(s.basic_pay,0),COALESCE(d.salary_advance,0),e.status,e.joining_date,e.leaving_date FROM employee_master_data e LEFT JOIN attendance a ON a.employee_id=e.employee_id AND a.month=? AND a.fy IN (?,?) AND a.is_deleted=0 LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy IN (?,?) AND s.is_deleted=0 LEFT JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy IN (?,?) AND d.is_deleted=0 WHERE e.is_deleted=0 ORDER BY e.employee_id";try(Connection c=DBConnection.getConnection();PreparedStatement q=c==null?null:c.prepareStatement(sql)){if(q==null)return;int i=1;for(int pair=0;pair<3;pair++){q.setString(i++,month);q.setString(i++,fy);q.setString(i++,expandedFy);}ResultSet r=q.executeQuery();while(r.next()){Employee employee=employees.get(r.getString(1));if(employee==null||!activeStatus(r.getString(9))||!eligible(r.getString(10),r.getString(11),period))continue;double basic=r.getDouble(7),epfWages=basic>=15000&&r.getInt(4)!=0?15000:basic,epsWages=Math.min(epfWages,15000),edliWages=Math.min(epfWages,15000),epf=Money.round(epfWages*epfRate/100),eps=Money.round(epsPercentage?epsWages*epsValue/100:epsValue),ncp=Math.max(0,r.getDouble(5)-r.getDouble(6));model.addRow(new Object[]{r.getString(1),r.getString(2),r.getString(3),EarningsAndAllowancesPanel.epfGrossWages(employee,period),Money.round(epfWages),Money.round(epsWages),Money.round(edliWages),epf,eps,Money.round(epf-eps),Money.round(ncp),Money.round(r.getDouble(8))});}}catch(SQLException ignored){}}
  private void loadTds(YearMonth period){String fy=FinancialYear.text(period.getMonthValue()>=4?period.getYear():period.getYear()-1),expandedFy=period.getMonthValue()>=4?period.getYear()+"-"+(period.getYear()+1):(period.getYear()-1)+"-"+period.getYear(),month=FinancialYear.shortName(period);String sql="SELECT e.employee_id,e.employee_name,COALESCE(s.gross_salary,0),COALESCE(d.income_tax_tds,0),e.status,e.joining_date,e.leaving_date FROM employee_master_data e LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy IN (?,?) AND s.is_deleted=0 LEFT JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy IN (?,?) AND d.is_deleted=0 WHERE e.is_deleted=0 ORDER BY e.employee_id";try(Connection c=DBConnection.getConnection();PreparedStatement q=c==null?null:c.prepareStatement(sql)){if(q==null)return;int i=1;for(int pair=0;pair<2;pair++){q.setString(i++,month);q.setString(i++,fy);q.setString(i++,expandedFy);}ResultSet r=q.executeQuery();while(r.next()){if(!activeStatus(r.getString(5))||!eligible(r.getString(6),r.getString(7),period))continue;model.addRow(new Object[]{r.getString(1),r.getString(2),Money.round(r.getDouble(3)),Money.round(r.getDouble(4))});}}catch(SQLException ignored){}}
  private void loadBankPayment(YearMonth period){String fy=FinancialYear.text(period.getMonthValue()>=4?period.getYear():period.getYear()-1),expandedFy=period.getMonthValue()>=4?period.getYear()+"-"+(period.getYear()+1):(period.getYear()-1)+"-"+period.getYear(),month=FinancialYear.shortName(period);String sql="SELECT e.employee_id,e.employee_name,e.bank_name,e.bank_acc,e.ifsc,COALESCE(s.net_salary,0),e.status,e.joining_date,e.leaving_date FROM employee_master_data e LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy IN (?,?) AND s.is_deleted=0 WHERE e.is_deleted=0 ORDER BY e.employee_id";try(Connection c=DBConnection.getConnection();PreparedStatement q=c==null?null:c.prepareStatement(sql)){if(q==null)return;q.setString(1,month);q.setString(2,fy);q.setString(3,expandedFy);ResultSet r=q.executeQuery();while(r.next()){if(!activeStatus(r.getString(7))||!eligible(r.getString(8),r.getString(9),period))continue;model.addRow(new Object[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),Money.round(r.getDouble(6))});}}catch(SQLException ignored){}}
  private boolean activeStatus(String status){String value=status==null?"":status.trim().toUpperCase(Locale.ROOT);return value.contains("ACTIVE")&&!value.contains("INACTIVE")&&!value.contains("EX-")&&!value.contains("RESIGN")&&!value.contains("DELETE");}
  private boolean eligible(String joining,String leaving,YearMonth period){LocalDate start=period.atDay(1),end=period.atEndOfMonth(),join=date(joining),leave=date(leaving);return (join==null||!join.isAfter(end))&&(leave==null||!leave.isBefore(start));}
  private LocalDate date(String value){if(value==null||value.trim().isEmpty())return null;String text=value.trim();for(java.time.format.DateTimeFormatter format:new java.time.format.DateTimeFormatter[]{java.time.format.DateTimeFormatter.ofPattern("dd-MM-uuuu"),java.time.format.DateTimeFormatter.ofPattern("dd/MM/uuuu"),java.time.format.DateTimeFormatter.ISO_LOCAL_DATE})try{return LocalDate.parse(text.length()>10?text.substring(0,10):text,format);}catch(Exception ignored){}return null;}
  private void load(YearMonth p){String month=FinancialYear.shortName(p),attendanceMonth=p.toString(),fy=FinancialYear.text(p.getMonthValue()>=4?p.getYear():p.getYear()-1),active="e.is_deleted=0 AND UPPER(TRIM(COALESCE(e.status,''))) IN ('ACTIVE','ACTIVE EMPLOYEE')",dmy="(substr(%s,7,4)||'-'||substr(%s,4,2)||'-'||substr(%s,1,2))",eligible="("+String.format(dmy,"e.joining_date","e.joining_date","e.joining_date")+" <= ? OR TRIM(COALESCE(e.joining_date,''))='') AND ("+String.format(dmy,"e.leaving_date","e.leaving_date","e.leaving_date")+" >= ? OR TRIM(COALESCE(e.leaving_date,''))='')";String sql=switch(type){case 0->"SELECT e.employee_id,e.esic,e.employee_name,a.days_payable,s.basic_pay,d.esic FROM employee_master_data e JOIN attendance a ON a.employee_id=e.employee_id AND a.month=? AND a.fy=? AND a.is_deleted=0 JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy=? AND s.is_deleted=0 JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy=? AND d.is_deleted=0 WHERE "+active+" AND "+eligible+" AND e.esic IS NOT NULL AND TRIM(e.esic)<>'' AND UPPER(TRIM(e.esic)) NOT IN ('NA','N/A') AND s.basic_pay<=(SELECT esic_wage_threshold FROM settings_deduction_rules WHERE is_deleted=0 ORDER BY id LIMIT 1) ORDER BY e.employee_id";case 1->"SELECT e.employee_id,e.employee_name,e.uan,COALESCE(s.basic_pay,0),COALESCE(d.epf,0) FROM employee_master_data e LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy=? AND s.is_deleted=0 LEFT JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy=? AND d.is_deleted=0 WHERE "+active+" AND "+eligible+" ORDER BY e.employee_id";case 2->"SELECT e.employee_id,e.employee_name,COALESCE(d.income_tax_tds,0) FROM employee_master_data e LEFT JOIN deductions d ON d.employee_id=e.employee_id AND d.month=? AND d.fy=? AND d.is_deleted=0 WHERE "+active+" AND "+eligible+" ORDER BY e.employee_id";default->"SELECT e.employee_id,e.employee_name,e.bank_name,e.bank_acc,e.ifsc,COALESCE(s.net_salary,0) FROM employee_master_data e LEFT JOIN salary s ON s.employee_id=e.employee_id AND s.month=? AND s.fy=? AND s.is_deleted=0 WHERE "+active+" AND "+eligible+" ORDER BY e.employee_id";};try(Connection c=DBConnection.getConnection();PreparedStatement q=c==null?null:c.prepareStatement(sql)){if(q==null)return;int i=1;if(type==0){q.setString(i++,attendanceMonth);q.setString(i++,fy);q.setString(i++,month);q.setString(i++,fy);q.setString(i++,month);q.setString(i++,fy);}else{int pairs=type==1?2:1;for(int pair=0;pair<pairs;pair++){q.setString(i++,month);q.setString(i++,fy);}}q.setString(i++,p.atEndOfMonth().toString());q.setString(i,p.atDay(1).toString());ResultSet r=q.executeQuery();while(r.next()){Object[] row=new Object[model.getColumnCount()];for(int column=0;column<row.length;column++)row[column]=(column>=3||(type==2&&column==2))?Money.round(r.getDouble(column+1)):r.getString(column+1);model.addRow(row);}}catch(SQLException ignored){}}
  private void export(){JFileChooser chooser=new JFileChooser();if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;File f=chooser.getSelectedFile();if(!f.getName().toLowerCase().endsWith(".xlsx"))f=new File(f.getParentFile(),f.getName()+".xlsx");java.util.List<Object[]> rows=new ArrayList<>();for(int r=0;r<model.getRowCount();r++){Object[] row=new Object[model.getColumnCount()];for(int c=0;c<row.length;c++)row[c]=model.getValueAt(r,c);rows.add(row);}try{PayrollExcel.write(f,title(),columns(),rows);JOptionPane.showMessageDialog(this,"Report exported successfully.");}catch(Exception ex){JOptionPane.showMessageDialog(this,"Export failed: "+ex.getMessage());}}
 }
}
